import requests

def check_for_loops(url):
    response = requests.get(url)
    return response.status_code == 200 and response.json()

def check_for_excessive_requests(url):
    response = requests.get(url)
    return response.status_code == 429 or response.json()['error'] == 'Too many requests'

def check_for_spam(url):
    response = requests.get(url)
    return response.status_code == 4  # 4 is the status code for spam in HTTP

